import {contributionHtml} from './contribution-ui.mjs';
import {marketHtml,bindMarketPanels} from './market-ui.mjs';
import {prepareSimulation,validateSimulationLineups} from './player-simulation.mjs?v=2026-10-31.2';
import {createSimulationJob} from './simulation-job.mjs?v=2026-10-31.2';
import {createSimulationSessions} from './simulation-session.mjs';
import {simulationMarketsHtml,bindSimulationMarkets} from './simulation-markets-ui.mjs';
let current=null;
const sessions=createSimulationSessions();
const roles={0:'Kaleci',1:'Defans',2:'Orta saha',3:'Forvet'};
const channels={attack:'Hücum',creation:'Oyun kurma',defense:'Savunma',keeper:'Kaleci'};
const newSeed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
export function stopSimulation(recalculating=false){
 current?.job.cancel();current?.stopReplay();
 if(recalculating&&current){
  current.pending=true;
  const button=current.root.querySelector('#sim-run'),status=current.root.querySelector('#sim-status');
  if(button)button.disabled=true;
  if(status)status.textContent='Seçilen model hazırlanıyor. Tamamlandığında simülasyonu çalıştırabilirsiniz.';
 }
}
export function renderSimulation(root,ctx){
 if(current?.analysis===ctx.result)return;
 stopSimulation();
 const {esc,number,pct}=ctx;
 let input;
 try{input=prepareSimulation(ctx.bundle,ctx.result,ctx.options);}
 catch(error){root.innerHTML=`<p class="empty">${esc(error.message)}</p>`;current=null;return;}
 const restored=sessions.restore(input);
 const state={analysis:ctx.result,input,root,pending:false,lineups:restored.lineups,result:null,timer:null,minute:90,seed:restored.seed,job:null,stopReplay(){if(this.timer!==null){clearInterval(this.timer);this.timer=null;}const button=root.querySelector('#sim-play');if(button)button.textContent='Örnek maçı oynat ▶';}};
 current=state;
 const q=s=>root.querySelector(s);
 const player=(team,id)=>team.players.find(p=>p.id===String(id));
 const coverageText=(p,team)=>`Kişisel: ${p.games??0} maç · ${number(p.minutes??0,0)} dk. Takımın son ${team.coverage.historyCount} maçında: ${p.teamGames??0} maç · ${number(p.teamMinutes??0,0)} dk. Lig gücü: ${p.strengthScope?.games??0} maç.${p.positionEvidence?' Mevki kaynağı: '+new Date(p.positionEvidence.date).toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul'})+' resmî maç kadrosu.':''}`;
 const scoreText=(v)=>number(v,2);
 function invalidate(){state.job.cancel();state.stopReplay();state.result=null;q('#sim-results').innerHTML='<p class="empty">Senaryo değişti. Simülasyonu yeniden çalıştırın.</p>';q('#sim-status').textContent='Yeni senaryo hazır.';}
 function roster(){
  q('#sim-rosters').innerHTML=input.teams.map(team=>`<section class="card sim-roster"><div class="card-title"><h2>${esc(team.name)}</h2><span class="tag">${team.side==='home'?'EV SAHİBİ':'DEPLASMAN'}</span></div><p class="inline-note">Önceki maç: ${team.previousMatch.id?`<a href="https://www.fotmob.com/match/${encodeURIComponent(team.previousMatch.id)}" target="_blank" rel="noreferrer">${esc(new Date(team.previousMatch.date).toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul'}))}</a>`:'kayıt yok'}. İlk 11’i seçin. Seçimden çıkan futbolcu yedeklere geçer; kadrodaki bir oyuncuyu seçmek iki yeri değiştirir.</p><div class="sim-slots">${Array.from({length:11},(_,slot)=>{const id=state.lineups[team.id][slot],p=player(team,id);return `<label class="sim-slot"><span>${slot+1}</span><select data-sim-team="${esc(team.id)}" data-sim-slot="${slot}" aria-label="${esc(team.name)} ilk 11 sıra ${slot+1}">${!p?'<option value="">Oyuncu seçin</option>':''}${team.players.map(candidate=>`<option value="${esc(candidate.id)}" ${candidate.id===id?'selected':''} ${candidate.eligible?'':'disabled'}>${esc(candidate.name)} · ${roles[candidate.position]??'Mevki bilinmiyor'}${candidate.eligible?'':' · Kullanılamıyor'}</option>`).join('')}</select><small>${p?esc(coverageText(p,team)):''}</small></label>`;}).join('')}</div><details class="sim-availability"><summary>Sakat / eksik oyuncu senaryosu</summary><p class="inline-note">Bu seçim genel bakıştaki kadro girdisini ve simülasyon başlangıcını günceller. “Oynayabilir” kaynakta eksik görünen oyuncu için açık kullanıcı varsayımıdır.</p>${team.players.map(p=>`<label>${esc(p.name)}<select data-availability="${esc(p.id)}" aria-label="${esc(p.name)} uygunluk"><option value="" ${!ctx.options.playerScenarios?.[p.id]?'selected':''}>Kaynak / önceki maç</option><option value="out" ${ctx.options.playerScenarios?.[p.id]==='out'?'selected':''}>Sakat / eksik</option><option value="in" ${ctx.options.playerScenarios?.[p.id]==='in'?'selected':''}>Oynayabilir · varsayım</option></select></label>`).join('')}</details><h3 class="sim-bench-title">Yedekler · son maçlardaki aday havuzu</h3><div class="sim-bench">${team.players.filter(p=>!state.lineups[team.id].includes(p.id)).map(p=>`<div class="${p.eligible?'':'muted'}"><b>${esc(p.name)}</b><small>${roles[p.position]??'Mevki bilinmiyor'} · ${esc(coverageText(p,team))}${p.eligible?'':' · '+esc(p.unavailableReason??'Kaynakta eksik')}</small></div>`).join('')||'<p class="inline-note">Uygun yedek yok.</p>'}</div>${team.replacements?.length?`<p class="inline-note">Otomatik kadro düzeltmesi: ${team.replacements.map(r=>esc(r.outName)+' → '+esc(r.inName??'Aynı mevkide uygun yedek yok')).join('; ')}</p>`:''}</section>`).join('');
  root.querySelectorAll('[data-availability]').forEach(select=>select.onchange=()=>{ctx.options.playerScenarios??={};if(select.value)ctx.options.playerScenarios[select.dataset.availability]=select.value;else delete ctx.options.playerScenarios[select.dataset.availability];ctx.recalculate();});
  root.querySelectorAll('[data-sim-slot]').forEach(select=>select.onchange=()=>{const ids=state.lineups[select.dataset.simTeam],slot=Number(select.dataset.simSlot),old=ids[slot],other=ids.indexOf(select.value);if(other!==-1)ids[other]=old;ids[slot]=select.value;sessions.saveLineups(input,state.lineups);invalidate();roster();});
 }
 function start(){
  if(state.pending)return;
  state.stopReplay();
  const raw=q('#sim-seed').value.trim(),seed=Number(raw);
  if(!raw||!Number.isInteger(seed)||seed<0||seed>4294967295){q('#sim-status').textContent='Tohum 0–4294967295 aralığında tam sayı olmalı.';return;}
  try{validateSimulationLineups(input,state.lineups);}catch(error){q('#sim-status').textContent=error.message;return;}
  state.seed=seed;sessions.saveSeed(input,seed);state.result=null;q('#sim-results').innerHTML='';
  state.job.start(input,{iterations:10000,seed,lineups:state.lineups});
 }
 root.innerHTML=`<div class="notice sim-notice" id="sim-training"><b>Geçmiş sonuçlardan öğrenme: ${input.training?.accepted?'etkin':'takım tabanı'}.</b> ${input.training?.counts?.eligible??0} uygun geçmiş maç · ${input.training?.counts?.test??0} ayrı test maçı. <b>${input.training?.gbdt?.active?input.training?.marketNetwork?.active?"Pazar ağı + GBDT + ilk 11":"GBDT + ilk 11":"Oyuncu ağı"}: ${input.training?.gbdt?.active?input.training.gbdt.experimental?"deneysel olarak etkin":"etkin":input.training?.playerGraph?.active?input.training.playerGraph.status==='experimental'?'deneysel olarak etkin':'etkin':'otomatik seçim / takım modeli'}.</b> Skor projeksiyonu ile aynı eğitilmiş gol tabanı ve ${input.goalShape?'negatif binom':'Poisson'} dağılımı kullanılır; seçtiğiniz kadro ve değişiklikler bu tabanı günceller.</div><div class="section-heading"><h2>İki kadro. 10.000 olası maç.</h2><span class="tag">OYUNCU SİMÜLASYONU</span></div><p class="section-desc">İlk 11’leri karşılaştırın; yedekler geçmiş sürelerine göre gerçekçi değişikliklerle girsin. Kartlarda kişisel son ${input.formCount} maç ile takımın son ${input.formCount} maçındaki katılım ayrı gösterilir. Birim gücü ve geçmiş takım kıyası yalnızca hedef ligdeki maçlardan hesaplanır. Bu ayrı bir senaryo modelidir; genel bakıştaki tahmini değiştirmez.</p><div class="notice sim-notice"><b>Kadro kaynağı: Bir önceki resmî maçın ilk 11’i + eksik oyuncu düzeltmeleri.</b> ${ctx.bundle.target.started||ctx.bundle.target.finished?'Geçmiş maç için senaryo gösterilir; maç öncesinde doğrulanmış tahmin değildir.':''} Sonradan görülen sakatlık kayıtları otomatik uygulanmaz; aşağıda açık senaryo seçebilirsiniz. Her takım tam bir kaleciyle başlar. Doğrulanmış önceki resmî ilk 11 kadrosunun genel mevki dağılımı korunur; bekler kaynakta orta saha olarak kayıtlı olabilir. Bu dağılımdan farklı bir kadro seçerseniz en az 3 defans, 2 orta saha ve 1 forvet gerekir. En fazla 5 değişiklik, 3 pencere, pencere başına 3 değişiklik ve 90 dakika kullanılır.</div><div class="grid two" id="sim-rosters"></div><section class="card sim-controls"><div><label for="sim-seed">Rastgelelik tohumu</label><input id="sim-seed" class="filter-input" type="number" min="0" max="4294967295" step="1" value="${state.seed}"><small>Aynı veri, model, kadro ve tohum aynı sonucu verir. Model geçişinde tohum korunur.</small></div><button id="sim-run" class="button primary">10.000 maç simüle et ↗</button><button id="sim-new-seed" class="button ghost">Yeni tohum</button><button id="sim-reset" class="button ghost">Başlangıç kadrosuna dön</button><p id="sim-status" role="status">Kadroları seçip simülasyonu başlatın.</p></section><div id="sim-results"></div><details class="card sim-method"><summary>Varsayımlar, veri kapsamı ve hesaplama</summary><p>Başlangıç gol yoğunlukları skor projeksiyonuyla aynı takım ve eğitim tabanından gelir: ${number(input.baseMeans.home,2)} – ${number(input.baseMeans.away,2)}. ${input.gbdtScenario?"GBDT, seçilen 11 ve her değişiklik sonrası sahadaki oyuncuların detaylı geçmişini yeniden değerlendirir. Eski oyuncu çarpanı eklenmez.":"Oyuncu etkisi, seçili kadro ile takımın aynı ligdeki geçmiş dakika dağılımı arasındaki farktır."} Oyuncu profili ve lig/mevki referansı aynı turnuva havuzundan gelir; kupa ve Avrupa maçları bu kıyasa karışmaz. Lig verisi yetersizse ilgili birim etkisi nötr kalır. Böylece aynı oyuncu gücü iki kez eklenmez.</p><p>Aynı lig ve mevkideki referansa göre hücum (xG, gol, şut), oyun kurma (xA, fırsat, pas), savunma (top kapma, pas arası, defansif hamle) ve kaleci (önlenen gol) karşılaştırılır. Eksik veri tarafsız öncüle yaklaşır; gözlenmiş sıfır sayılmaz. Küçük örneklemler küçültülür.</p><p>${input.gbdtScenario?"GBDT etkin: her safhada aynı "+(input.training?.featureNames?.length??0)+" girdi ve aynı ağaçlar kullanılır. Aşağıdaki katsayılar yalnız diğer model seçenekleri içindir. ":""}Gol yoğunluğu çarpanı: exp(0,20 × kendi hücum farkı + 0,12 × kendi oyun kurma farkı − 0,16 × rakip savunma farkı − 0,12 × rakip kaleci farkı). Çarpan 1/1,35–1,35 aralığında tutulur. Bunlar henüz bağımsız veride kalibre edilmemiş model varsayımlarıdır.</p><p>Yedekler aynı mevkide, takımın son maçlarındaki katılım ve yedekten giriş sıklığına göre seçilir. Üç değişiklik penceresinin öncül ağırlıkları %25 / %45 / %30’dur; gözlenen çıkış dakikaları bu dağılımı günceller. Bir pencereye en fazla 3 değişiklik atanır. Kaleci değişimi, uzatma, sakatlık ve kart üretilmez. Her yedeğin oyuna girmesi gerekmez. Golcü seçimi %70 xG/90 ve %30 gol/90 karışımına dayanır; küçük örneklem, dakika / (dakika + 270) ile mevki öncülüne küçültülür ve küçük bir olasılık tabanı kullanılır. xG ve gol ölçümlerinin ikisi de eksikse golcü ağırlığı bilinmiyor kalır; gol takım adına gösterilebilir. Gösterilen golcü bir senaryo seçimidir.</p><p>Eğitim etkinse genel bakış ve simülasyon aynı öğrenilmiş gol tabanını ve seçilen dağılımı kullanır. Negatif binom seçilmişse maç boyunca korunan bir rastgele gol yoğunluğu, yüksek skorlu sonuçların sıklığını da yansıtır. Genel bakış mevcut oyuncu/H2H katmanlarını uygular; simülasyon seçtiğiniz ilk 11 ve değişiklikleri uygular. Bu simülasyon H2H düzeltmesini ayrıca eklemez. Eğitim etkin değilse genel bakıştaki benzer skor karışımı simülasyonda kullanılmaz. Bu yüzden iki ekrandaki gol, 1X2, üst ve KG olasılıkları farklı olabilir. Monte Carlo örneklemesi de küçük farklar üretir.</p><p>${input.limitations.map(esc).join('<br>')}</p><p>Standart beş değişiklik senaryosu için <a href="https://www.theifab.com/laws/latest/the-players/" target="_blank" rel="noreferrer">IFAB Kural 3 ↗</a></p><details><summary>Hesaplama politikası ve kapsam ayrıntıları</summary><pre>${esc(JSON.stringify({policy:input.policy,coverage:input.coverage,teams:input.teams.map(t=>({id:t.id,name:t.name,coverage:t.coverage,baseline:t.baseline}))},null,2))}</pre></details></details>`;
 state.job=createSimulationJob({createWorker:()=>new Worker('/simulation-worker.mjs?v=2026-10-31.2',{type:'module'}),onState:s=>{
  q('#sim-run').disabled=state.pending||s.status==='running';
  q('#sim-status').textContent=s.status==='running'?'10.000 maç hesaplanıyor…':s.status==='cancelled'?'Hesap iptal edildi. Yeniden çalıştırabilirsiniz.':s.status==='error'?s.error:'10.000 maç tamamlandı. Sonuçlar aşağıda.';
  if(s.status==='complete'){state.result=s.result;results();}
 }});
 roster();q('#sim-run').onclick=start;
 q('#sim-new-seed').onclick=()=>{invalidate();state.seed=newSeed();sessions.saveSeed(input,state.seed);q('#sim-seed').value=state.seed;};
 q('#sim-seed').oninput=()=>{const raw=q('#sim-seed').value.trim();if(raw&&sessions.saveSeed(input,Number(raw)))state.seed=Number(raw);invalidate();};
 q('#sim-reset').onclick=()=>{invalidate();sessions.resetLineups(input);state.lineups=Object.fromEntries(input.teams.map(t=>[t.id,[...t.defaultLineup]]));roster();};
 if(restored.reset)q('#sim-status').textContent='Önceki kadro yeni uygunluk verisine uymadığı için başlangıç kadrosu yüklendi. Tohum korundu.';
 function results(){
  const r=state.result,p=r.probabilities,top=r.topScores[0];state.minute=90;
  const totals=new Map();for(const row of r.histogram){const n=row.home+row.away;totals.set(n,(totals.get(n)??0)+row.probability);}
  q('#sim-results').innerHTML=`<div class="grid two"><section class="card"><div class="card-title"><h2>En olası skor</h2><span class="tag">${r.iterations.toLocaleString('tr-TR')} TEKRAR</span></div><div class="big-score"><strong>${top.home}<span>:</span>${top.away}</strong><div class="score-caption"><b>${pct(top.probability)}</b>tek skorun olasılığı</div></div><div class="probability-bar"><div style="width:${p.home*100}%"></div><div style="width:${p.draw*100}%"></div><div style="width:${p.away*100}%"></div></div><div class="probability-labels"><div>EV / 1<b>${pct(p.home)}</b></div><div>BERABERLİK / X<b>${pct(p.draw)}</b></div><div>DEP / 2<b>${pct(p.away)}</b></div></div><div class="prediction-foot"><span>Ortalama gol <b>${number(r.means.home,2)} – ${number(r.means.away,2)}</b></span><span>Tohum: ${r.seed}</span></div><p class="inline-note">Sonuçlar örneklenmiş senaryo frekanslarıdır. En olası skor da kesin sonuç değildir.</p><button id="sim-export" class="button ghost">Simülasyon JSON indir ↓</button></section><section class="card"><div class="card-title"><h2>Gol dağılımı</h2></div><div class="mini-stats"><div><b>${pct(p.over25)}</b><span>2,5 ÜST</span></div><div><b>${pct(p.under25)}</b><span>2,5 ALT</span></div><div><b>${pct(p.btts)}</b><span>KARŞILIKLI GOL</span></div></div><div class="sim-goals">${[...totals].sort((a,b)=>a[0]-b[0]).map(([goals,prob])=>`<div><span>${goals} gol</span><div><i style="width:${prob*100}%"></i></div><b>${pct(prob)}</b></div>`).join('')}</div><details><summary>Skor seçenekleri</summary><div class="score-list">${r.topScores.slice(0,12).map(row=>`<div class="score-chip"><strong>${row.home} – ${row.away}</strong><span>${pct(row.probability)}</span></div>`).join('')}</div><p class="inline-note">Tüm skorlar, kuyruk kesilmeden JSON çıktısında bulunur.</p></details></section></div><div id="sim-betting-summary"></div><section class="card sim-replay"><div class="card-title"><h2>Bir örnek maç</h2><span class="tag">10.000 MAÇTAN BİRİ</span></div><p class="inline-note">Bu akış en olası skorun canlandırması değildir; kaydedilen tek bir tekrarın gollerini ve değişikliklerini gösterir.</p><div class="sim-scoreboard"><span>${esc(input.teams[0].name)}</span><strong id="sim-score"></strong><span>${esc(input.teams[1].name)}</span></div><div class="sim-replay-controls"><button id="sim-play" class="button primary">Örnek maçı oynat ▶</button><label for="sim-minute">Dakika <b id="sim-clock">90′</b></label><input id="sim-minute" type="range" min="0" max="90" step="1" value="90"></div><div id="sim-onpitch" class="sim-pitch"></div><ol id="sim-events" class="sim-events"></ol></section><section class="card"><h2>Kafa kafaya: birim karşılaştırması</h2><p class="inline-note">Oyuncu profilleri, lig/mevki referansı ve geçmiş takım dağılımı aynı lig kapsamındadır. Birim değerleri bu referansa göre küçültülmüş göreli farktır; rating veya gol olasılığı değildir. Hücum ve oyun kurma rakibin savunması/kalecisiyle karşılaştırılır.</p><div class="table-wrap"><table><thead><tr><th>TAKIM / BİRİM</th><th>SEÇİLEN İLK 11</th><th>GEÇMİŞ TAKIM DAĞILIMI</th><th>FARK</th><th>KAPSAM: SEÇİLİ / GEÇMİŞ</th></tr></thead><tbody>${r.comparisons.map(team=>Object.entries(channels).map(([key,label])=>`<tr><td>${esc(team.name)} · ${label}</td><td>${scoreText(team.selected[key])}</td><td>${scoreText(team.historical[key])}</td><td>${scoreText(team.delta[key])}</td><td>${(typeof team.coverage[key]==='number'?pct(team.coverage[key]):'—')+' / '+(typeof team.historicalCoverage?.[key]==='number'?pct(team.historicalCoverage[key]):'—')}</td></tr>`).join('')).join('')}</tbody></table></div></section><details class="card sim-usage"><summary>İlk 11 ve yedeklerin simülasyondaki süreleri</summary><div class="table-wrap"><table><thead><tr><th>OYUNCU</th><th>TAKIM</th><th>OYUNA GİRME</th><th>ORTALAMA DAKİKA</th></tr></thead><tbody>${r.usage.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(input.teams.find(t=>t.id===p.teamId)?.name??p.teamId)}</td><td>${pct(p.appearanceProbability)}</td><td>${number(p.averageMinutes,1)}</td></tr>`).join('')}</tbody></table></div></details>`;
  q('#sim-betting-summary').innerHTML=simulationMarketsHtml(r.bettingSummary,{esc,number,teams:input.teams});
  bindSimulationMarkets(q('#sim-results'),r.bettingSummary,{esc,pct,download:ctx.download,matchId:input.matchId,seed:r.seed});
  q('#sim-results').insertAdjacentHTML('beforeend',contributionHtml(r.contributions,{esc,number,pct})+marketHtml(input.marketAnalysis,{esc,number,pct,id:'market-simulation',simulationProbabilities:r.marketProbabilities}));bindMarketPanels(q('#sim-results'),input.marketAnalysis,r.histogram,{pct});
  q('#sim-export').onclick=()=>ctx.download(`mathgoal-simulation-${input.matchId}-${r.seed}.json`,{input,settings:{lineups:state.lineups,iterations:r.iterations,seed:r.seed},result:r});
  q('#sim-play').onclick=()=>{if(state.timer!==null){state.stopReplay();return;}if(state.minute>=90)state.minute=0;replay();q('#sim-play').textContent='Duraklat Ⅱ';state.timer=setInterval(()=>{state.minute=Math.min(90,state.minute+1);replay();if(state.minute===90)state.stopReplay();},220);};
  q('#sim-minute').oninput=e=>{state.stopReplay();state.minute=Number(e.target.value);replay();};replay();
 }
 function replay(){
  if(!state.result)return;
  const events=state.result.sample.events.filter(e=>e.minute<=state.minute),goals=events.filter(e=>e.type==='goal');
  q('#sim-clock').textContent=state.minute+'′';q('#sim-minute').value=state.minute;
  q('#sim-score').textContent=goals.filter(e=>e.side==='home').length+' : '+goals.filter(e=>e.side==='away').length;
  q('#sim-onpitch').innerHTML=input.teams.map(team=>{let ids=[...(state.result.sample.lineups?.[team.id]??state.lineups[team.id])];for(const e of events.filter(e=>e.type==='substitution'&&e.teamId===team.id)){const index=ids.indexOf(e.outId);if(index>=0)ids[index]=e.inId;}return `<div><h3>${esc(team.name)} <small>SAHADA</small></h3>${ids.map(id=>{const p=player(team,id);return `<span><small>${roles[p?.position]??'?'}</small>${esc(p?.name??id)}</span>`;}).join('')}</div>`;}).join('');
  q('#sim-events').innerHTML=events.map(e=>`<li class="${e.side}"><time>${number(e.minute,0)}′</time><span>${e.type==='goal'?`⚽ Gol · ${esc(e.name??input.teams.find(t=>t.id===e.teamId)?.name??'Takım golü')}`:`↔ ${esc(e.outName)} → ${esc(e.inName)}`}</span><small>${esc(input.teams.find(t=>t.id===e.teamId)?.name??'')}</small></li>`).join('')||'<li>Henüz gol veya oyuncu değişikliği yok.</li>';
 }
}
